import functools

def plain(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def kept(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@plain
def area(w, h):
    """Rectangle area."""
    return w * h

@kept
def volume(w, h, d):
    """Box volume."""
    return w * h * d

print(area.__name__, area.__doc__)
print(volume.__name__, volume.__doc__)
print(area(2, 3), volume(1, 2, 3))

