def non_negative(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        for arg in args:
            if isinstance(arg, (int, float)) and arg < 0:
                raise ValueError("negative argument: " + str(arg))
        return func(*args, **kwargs)
    return wrapper

